(7286227, 1135601, 170281, '<td valign="top">Very cool.</td>', 'Very cool.', '2014-11-19 11:29:16.000000', NULL, 1),
(7286234, 1135684, 43565, '<td valign="top">Sorry, but a shriveled apple is not an inanimate object.</td>', 'Sorry, but a shriveled apple is not an inanimate object.', '2014-11-19 11:33:18.000000', NULL, 1),
(7286235, 1135595, 43565, '<td valign="top">The object in the upper right corner is a distraction for me.</td>', 'The object in the upper right corner is a distraction for me.', '2014-11-19 11:34:33.000000', NULL, 1),
(7286237, 1135710, 43565, '<td valign="top">A lime is not an inanimate object.</td>', 'A lime is not an inanimate object.', '2014-11-19 11:36:52.000000', NULL, 1),
(7286243, 1135637, 170576, '<td valign="top">Not sure about where it is focused.</td>', 'Not sure about where it is focused.', '2014-11-19 12:26:56.000000', NULL, 1),
(7286245, 1135608, 170576, '<td valign="top">It looked fine until you see the last 4, the edges get very rough</td>', 'It looked fine until you see the last 4, the edges get very rough', '2014-11-19 12:31:40.000000', NULL, 1),
(7286247, 1135475, 63218, '<td valign="top"><strike></strike></td>', '', '2014-11-19 12:45:53.000000', NULL, 1),
(7286299, 1135684, 30490, '<td valign="top">I faced a voting dilemma on this image.  On one hand the main subject is clearly something that was once living, which doesn''t meet the challenge criteria.  On the other hand, the subject is clearly no longer living and the spoon is inanimate....  What to do?  I compromised and decided to "bend" the rule (in my mind) for voting, because I think the overall image is well composed and has an interesting post processing texture to it.</td>', 'I faced a voting dilemma on this image.  On one hand the main subject is clearly something that was once living, which doesn''t meet the challenge criteria.  On the other hand, the subject is clearly no longer living and the spoon is inanimate....  What to do?  I compromised and decided to "bend" the rule (in my mind) for voting, because I think the overall image is well composed and has an interesting post processing texture to it.', '2014-11-19 14:02:08.000000', NULL, 1),
(7286302, 1135637, 30490, '<td valign="top">Macro doesn''t mean "Out of Focus".  Since most of the image is beyond blurry, I can''t rate it very high.  You could have cropped the image to show more of the in focus parts as a greater percentage of the image.</td>', 'Macro doesn''t mean "Out of Focus".  Since most of the image is beyond blurry, I can''t rate it very high.  You could have cropped the image to show more of the in focus parts as a greater percentage of the image.', '2014-11-19 14:06:52.000000', NULL, 1),
(7286303, 1135622, 30490, '<td valign="top">This is just too blurry for my taste.  Macro to me means something up close but still in focus.  If the water  coming out of the pipe had been a sharp focus this image would have worked much better.</td>', 'This is just too blurry for my taste.  Macro to me means something up close but still in focus.  If the water  coming out of the pipe had been a sharp focus this image would have worked much better.', '2014-11-19 14:07:58.000000', NULL, 1),
(7286304, 1135577, 30490, '<td valign="top">Kind of a macro... good job on the focus.  It just isn''t very compelling.</td>', 'Kind of a macro... good job on the focus.  It just isn''t very compelling.', '2014-11-19 14:08:40.000000', NULL, 1),
(7286305, 1135674, 30490, '<td valign="top">Not a bad idea, but it needed to have good sharp focus in my opinion.</td>', 'Not a bad idea, but it needed to have good sharp focus in my opinion.', '2014-11-19 14:09:12.000000', NULL, 1),
(7286306, 1135537, 30490, '<td valign="top">Not sure what I am looking at, which is a okay for a Macro image.  This has some nice texture and light, but isn''t real compelling.  Kind of like the title - life less.</td>', 'Not sure what I am looking at, which is a okay for a Macro image.  This has some nice texture and light, but isn''t real compelling.  Kind of like the title - life less.', '2014-11-19 14:10:24.000000', NULL, 1),
(7286307, 1135533, 30490, '<td valign="top">I don''t care for your title, but didn''t rate the image down because of a title.  Overall this is an okay macro, I just find the dirt spots on the object to be a bit distracting.  I like the play of light over the different sized grooves.</td>', 'I don''t care for your title, but didn''t rate the image down because of a title.  Overall this is an okay macro, I just find the dirt spots on the object to be a bit distracting.  I like the play of light over the different sized grooves.', '2014-11-19 14:12:15.000000', NULL, 1),
(7286319, 1135477, 19825, '<td valign="top">Nice. Without the clever title I am not sure I''d have figured out what this was. It looked like three boxes in a snow drift.</td>', 'Nice. Without the clever title I am not sure I''d have figured out what this was. It looked like three boxes in a snow drift.', '2014-11-19 15:21:59.000000', NULL, 1),
(7286320, 1135713, 48710, '<td valign="top">What you would call a glamour photo of a gently used watch...</td>', 'What you would call a glamour photo of a gently used watch...', '2014-11-19 15:28:53.000000', NULL, 1),
(7286326, 1135657, 30490, '<td valign="top">A true macro shot!  Your image is so close up that one can''t figure out what the heck it is, and for this challenge that is a great thing!</td>', 'A true macro shot!  Your image is so close up that one can''t figure out what the heck it is, and for this challenge that is a great thing!', '2014-11-19 15:50:13.000000', NULL, 1),
(7286328, 1135665, 30490, '<td valign="top">This one is very different.  I like the idea overall, I just wish the focus was a bit more consistent.  A good effort for this challenge</td>', 'This one is very different.  I like the idea overall, I just wish the focus was a bit more consistent.  A good effort for this challenge', '2014-11-19 15:51:07.000000', NULL, 1),
(7286331, 1135647, 30490, '<td valign="top">I like the idea, but the very shallow focus just isn''t working for me.  Too much of the image is blurry.  If all of the paint bubbles on the nail head had been in focus it would have been a stronger image.  Still a good effort and a 5 from me.</td>', 'I like the idea, but the very shallow focus just isn''t working for me.  Too much of the image is blurry.  If all of the paint bubbles on the nail head had been in focus it would have been a stronger image.  Still a good effort and a 5 from me.', '2014-11-19 15:52:48.000000', NULL, 1),
(7286333, 1135688, 30490, '<td valign="top">A good idea, but something needs to be in focus for the image.  I wish the "worlds best grandpa" had been sharper with the face of the watch blurred.  A good attempt for this challenge.</td>', 'A good idea, but something needs to be in focus for the image.  I wish the "worlds best grandpa" had been sharper with the face of the watch blurred.  A good attempt for this challenge.', '2014-11-19 15:56:31.000000', NULL, 1),
(7286335, 1135695, 30490, '<td valign="top">A true macro....I don''t know what the heck I''m looking at!  Nice shapes and contrasts.</td>', 'A true macro....I don''t know what the heck I''m looking at!  Nice shapes and contrasts.', '2014-11-19 15:57:15.000000', NULL, 1),
(7286336, 1135723, 30490, '<td valign="top">I love the color and the shapes, I just wish that something was in focus and sharp.</td>', 'I love the color and the shapes, I just wish that something was in focus and sharp.', '2014-11-19 15:57:53.000000', NULL, 1),
(7286338, 1135534, 30490, '<td valign="top">Well, this qualifies as inanimate macro... not the most interesting rock in this challenge but you get a 5 for sticking to the topic.</td>', 'Well, this qualifies as inanimate macro... not the most interesting rock in this challenge but you get a 5 for sticking to the topic.', '2014-11-19 15:58:43.000000', NULL, 1),
