(7287520, 1135526, 30490, '<td valign="top">Not sure what the heck this is/  Like the crisp numbers, wish the button thingy was also in focus, but I know how hard that can be to execute.  a 6 from me</td>', 'Not sure what the heck this is/  Like the crisp numbers, wish the button thingy was also in focus, but I know how hard that can be to execute.  a 6 from me', '2014-11-24 19:12:56.000000', NULL, 1),
(7287521, 1135484, 30490, '<td valign="top">Like the end of the candle wick and the smoke.  Great lighting.</td>', 'Like the end of the candle wick and the smoke.  Great lighting.', '2014-11-24 19:13:32.000000', NULL, 1),
(7287522, 1135627, 30490, '<td valign="top">I can''t help but focus on the dirt on this phone.... Kind of grosses me out. Good capture and focus on the object though.</td>', 'I can''t help but focus on the dirt on this phone.... Kind of grosses me out. Good capture and focus on the object though.', '2014-11-24 19:14:30.000000', NULL, 1),
(7287523, 1135725, 30490, '<td valign="top">Nice image, I love the detail in the screw threads.  Bumping up!</td>', 'Nice image, I love the detail in the screw threads.  Bumping up!', '2014-11-24 19:15:03.000000', NULL, 1),
(7287524, 1135676, 30490, '<td valign="top">The parts that are crisp are really interesting, the blown out center not so much.  I think I might have cropped and minimized that center area.  Still got a 6 for a good effort from me.</td>', 'The parts that are crisp are really interesting, the blown out center not so much.  I think I might have cropped and minimized that center area.  Still got a 6 for a good effort from me.', '2014-11-24 19:16:15.000000', NULL, 1),
(7287525, 1135477, 30490, '<td valign="top">I really like this one now that I am seeing it for the second time.  Great idea and execution of the idea.  Bumping up to a 7</td>', 'I really like this one now that I am seeing it for the second time.  Great idea and execution of the idea.  Bumping up to a 7', '2014-11-24 19:16:50.000000', NULL, 1),
(7287548, 1135629, 114285, '<td valign="top">Awesome detail! 8</td>', 'Awesome detail! 8', '2014-11-24 22:42:58.000000', NULL, 1),
(7287549, 1135675, 114285, '<td valign="top">Sharp as!</td>', 'Sharp as!', '2014-11-24 22:43:15.000000', NULL, 1),
(7287550, 1135477, 114285, '<td valign="top">This is brilliant, not only a macro, but artistically done, the shallow dof is lush! My top mark goes to you.</td>', 'This is brilliant, not only a macro, but artistically done, the shallow dof is lush! My top mark goes to you.', '2014-11-24 22:44:35.000000', NULL, 1),
(7287552, 1135725, 114285, '<td valign="top">love the conversion, being a big sepia fan myself, front page stuff!</td>', 'love the conversion, being a big sepia fan myself, front page stuff!', '2014-11-24 22:45:38.000000', NULL, 1),
(7287553, 1135625, 114285, '<td valign="top">Not a big fan of water drops, but this is exceptional. The shape is undeniably emotional, well done.<br/> <br/>Ps would love to know how many you took! Front page for me.</td>', 'Not a big fan of water drops, but this is exceptional. The shape is undeniably emotional, well done. Ps would love to know how many you took! Front page for me.', '2014-11-24 22:47:50.000000', NULL, 1),
(7287561, 1135689, 108069, '<td valign="top">Great iridescent colors give this extra depth and some mystery.</td>', 'Great iridescent colors give this extra depth and some mystery.', '2014-11-24 23:13:18.000000', NULL, 1),
(7287563, 1135477, 108069, '<td valign="top">Pretty wild. I''m always very drawn to contrasting textures, and this is really special in that regard. Cool photo.</td>', 'Pretty wild. I''m always very drawn to contrasting textures, and this is really special in that regard. Cool photo.', '2014-11-24 23:15:30.000000', NULL, 1),
(7287585, 1135613, 156466, '<td valign="top">A little more sharpness at the bottom would have made this really pop.</td>', 'A little more sharpness at the bottom would have made this really pop.', '2014-11-25 06:54:36.000000', NULL, 1),
(7287586, 1135694, 156466, '<td valign="top">Nicely shot.  The slight off-center framing makes it feel off.  Perhaps a slight tilt or just go dead-center.</td>', 'Nicely shot.  The slight off-center framing makes it feel off.  Perhaps a slight tilt or just go dead-center.', '2014-11-25 06:56:50.000000', NULL, 1),
(7287587, 1135608, 156466, '<td valign="top">1st and 3rd pearl OOF is a problem.</td>', '1st and 3rd pearl OOF is a problem.', '2014-11-25 07:01:00.000000', NULL, 1),
(7287609, 1135527, 56502, '<td valign="top">A gem - but why would they write on top that it''s a camera?</td>', 'A gem - but why would they write on top that it''s a camera?', '2014-11-25 11:39:05.000000', NULL, 1);
